import fs from'node:fs';import assert from'node:assert/strict';import{hash,json}from'./bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-study-set-navigation',prep=json(stage+'/PREPARATION.json'),parent=json(prep.parent.path),site=prep.website;
assert.equal(hash(prep.parent.path),prep.parent.sha256);const adaptations=json(stage+'/HARNESS_ADAPTATIONS.json');
for(const r of adaptations.records){let text=fs.readFileSync(site+'/'+r.path,'utf8');assert.equal(hash(site+'/'+r.path),r.afterSha256);for(const [before,after]of [...r.edits].reverse()){assert.equal(text.split(after).length,2);text=text.replace(after,before);}assert.equal(text,fs.readFileSync(parent.website+'/'+r.path,'utf8'));}
const fix=json(stage+'/HISTORICAL_CONTEXT_FIX.json');assert.equal(hash(site+'/'+fix.target),fix.afterSha256);assert.equal(hash(parent.website+'/'+fix.target),fix.beforeSha256);let restored=fs.readFileSync(site+'/'+fix.target,'utf8');for(const seam of [...fix.inverseSeams].reverse()){assert.equal(restored.split(seam.after).length,2);restored=restored.replace(seam.after,seam.before);}assert.equal(restored,fs.readFileSync(parent.website+'/'+fix.target,'utf8'));
const changed=['components/HeadAtlasStudySet.tsx',...adaptations.records.map(r=>r.path),fix.target],added=['tests/head-study-set-navigation.test.ts'];
for(const r of parent.sourceRows){assert.equal(hash(parent.website+'/'+r.path),r.sha256);if(!changed.includes(r.path))assert.equal(hash(site+'/'+r.path),r.sha256,r.path);}
const rows=[...parent.sourceRows.map(r=>r.path),...added].sort().map(path=>({path,bytes:fs.statSync(site+'/'+path).size,sha256:hash(site+'/'+path)}));
const record={...parent,at:new Date().toISOString(),website:site,parent:prep.parent.path,parentSha256:prep.parent.sha256,preparation:{path:stage+'/PREPARATION.json',sha256:hash(stage+'/PREPARATION.json')},sourceRows:rows,sourcePaths:rows.length,changedAuthoredPaths:changed,newPaths:added,productSourceExactToParent:false,verification:{},historicalContextFix:{path:stage+'/HISTORICAL_CONTEXT_FIX.json',sha256:hash(stage+'/HISTORICAL_CONTEXT_FIX.json')},harnessAdaptations:{path:stage+'/HARNESS_ADAPTATIONS.json',sha256:hash(stage+'/HARNESS_ADAPTATIONS.json')},installed:false,normalPreviewChanged:false};
const file=stage+'/SOURCE_CANDIDATE_V2.json';fs.writeFileSync(file,JSON.stringify(record,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({source:file,sha256:hash(file),sourcePaths:rows.length,changed,added}));
